3	import { motion } from "framer-motion";
4	import type { HTMLAttributes } from "react";
5	
6	type Direction = "up" | "down" | "left" | "right";
7	
8	const directionOffsets: Record<Direction, { x: number; y: number }> = {
9	  up: { x: 0, y: 40 },
10	  down: { x: 0, y: -40 },
11	  left: { x: 40, y: 0 },
12	  right: { x: -40, y: 0 },
13	};
14	
15	export function ScrollReveal({
16	  children,
17	  direction = "up",
18	  delay = 0,
19	  duration = 0.5,
20	  className,
21	  ...props
22	}: {
23	  children: React.ReactNode;
24	  direction?: Direction;
25	  delay?: number;
26	  duration?: number;
27	} & HTMLAttributes<HTMLDivElement>) {
28	  const offset = directionOffsets[direction];
29	
30	  return (
31	    <motion.div
32	      initial={{ opacity: 0, x: offset.x, y: offset.y }}
33	      whileInView={{ opacity: 1, x: 0, y: 0 }}
34	      viewport={{ once: true, margin: "-100px" }}
35	      transition={{ duration, delay, ease: "easeOut" }}
36	      className={className}
37	      {...props}
38	    >
39	      {children}
40	    </motion.div>
41	  );
42	}
