export interface FaqItem {
  question: string;
  answer: string;
}

export const FAQ_ITEMS: FaqItem[] = [
  {
    question: "How quickly can we get started?",
    answer:
      "Once you subscribe, your dedicated delivery team is live within 12 hours. We set up your workspace, onboard your preferences, and begin accepting requests the same business day.",
  },
  {
    question: "What types of tasks can I submit?",
    answer:
      "Shopify development, WordPress builds, custom web development, Figma UI/UX design, landing pages, banner design, email templates, and ongoing maintenance tasks. Essentially any web execution task your agency handles.",
  },
  {
    question: "Is this white-label? Will my clients know?",
    answer:
      "100% white-label. All deliverables are unbranded and delivered under your agency name. We are your invisible backend team — your clients never know we exist.",
  },
  {
    question: "What if I'm not satisfied with the work?",
    answer:
      "We have a 14-day satisfaction guarantee. If you're not happy with the quality in your first two weeks, we'll make it right or refund you — no questions asked.",
  },
  {
    question: "Can I pause or cancel my subscription?",
    answer:
      "Yes. You can pause your subscription at any time with no penalty. Cancellations take effect at the end of your current billing period. There are no long-term contracts.",
  },
  {
    question: "How does task submission work?",
    answer:
      "You get a dedicated Smart Client Workspace — a streamlined dashboard where you submit requests, track progress in real time, leave feedback, and approve deliverables. No email chains, no scattered tools.",
  },
  {
    question: "What does 'dual-lane' or 'three-lane' mean?",
    answer:
      "Lanes refer to the number of tasks that can be actively worked on simultaneously. Single-lane means one task at a time. Dual-lane means two tasks can run in parallel. Three-lane means three simultaneous workstreams — ideal for high-volume agencies.",
  },
  {
    question: "Do you offer custom plans?",
    answer:
      "Yes. If your agency has specific volume, platform, or workflow needs that don't fit a standard plan, we'll build a custom arrangement. Book a demo and we'll design a plan around your exact requirements.",
  },
];

export type BillingPeriod = "monthly" | "quarterly" | "annually";

export interface PricingPlan {
  id: string;
  name: string;
  tagline: string;
  monthlyPrice: number;
  hours: number;
  lanes: string;
  platforms: string;
  workspace: string;
  popular: boolean;
