export function getDiscountedPrice(
  basePrice: number,
  period: BillingPeriod
): number {
  if (period === "quarterly") return Math.round(basePrice * 0.9);
  if (period === "annually") return Math.round(basePrice * 0.8);
  return basePrice;
}

"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";

const WORDS = ["Ownership Driven", "Without Hiring", "On Demand"];

export function Typewriter() {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setIndex((prev) => (prev + 1) % WORDS.length);
    }, 2200);
    return () => clearInterval(timer);
  }, []);

  return (
    <span className="relative inline-block min-w-[220px] text-left align-bottom">
      <AnimatePresence mode="wait">
        <motion.span
          key={WORDS[index]}
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -12 }}
          transition={{ duration: 0.3, ease: "easeOut" }}
          className="gradient-cyan-text inline-block whitespace-nowrap"
        >
          {WORDS[index]}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

