export function PortfolioCarousel() {
  const [emblaRef, emblaApi] = useEmblaCarousel(
    { loop: true, align: "center", slidesToScroll: 1 },
    [Autoplay({ delay: 3500, stopOnInteraction: false })]
  );
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [canScrollPrev, setCanScrollPrev] = useState(false);
  const [canScrollNext, setCanScrollNext] = useState(false);

  const onSelect = useCallback(() => {
    if (!emblaApi) return;
    setSelectedIndex(emblaApi.selectedScrollSnap());
    setCanScrollPrev(emblaApi.canScrollPrev());
    setCanScrollNext(emblaApi.canScrollNext());
  }, [emblaApi]);

  useEffect(() => {
    if (!emblaApi) return;
    emblaApi.on("select", onSelect);
    onSelect();
    return () => {
      emblaApi.off("select", onSelect);
    };
  }, [emblaApi, onSelect]);

  const scrollPrev = useCallback(() => emblaApi?.scrollPrev(), [emblaApi]);
  const scrollNext = useCallback(() => emblaApi?.scrollNext(), [emblaApi]);

  return (
    <section className="bg-white py-20 md:py-28">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        <ScrollReveal>
          <h2 className="mb-2 text-center text-[35px] font-bold leading-[45px] text-brand-navy">
            Our Work
          </h2>
          <p className="mx-auto mb-12 max-w-xl text-center text-base text-gray-500">
            A sample of what we deliver every week for agencies across industries
            and platforms.
          </p>
        </ScrollReveal>

        <ScrollReveal delay={0.1}>
          <div className="relative">
            {/* Carousel viewport */}
            <div className="overflow-hidden" ref={emblaRef}>
              <div className="flex gap-4 md:gap-6">
                {SLIDES.map((slide, i) => (
                  <div
                    key={i}
                    className="min-w-0 flex-[0_0_85%] sm:flex-[0_0_60%] md:flex-[0_0_42%] lg:flex-[0_0_32%]"
                  >
                    <div className="group overflow-hidden rounded-2xl shadow-[0_4px_24px_rgba(171,171,171,0.1)] transition-all duration-300 hover:shadow-[0_8px_32px_rgba(171,171,171,0.18)]">
                      {/* Image placeholder */}
                      <div
                        className={`relative flex h-52 items-center justify-center bg-gradient-to-br ${slide.bg} text-7xl`}
                      >
                        {slide.emoji}
                        <div className="absolute inset-0 bg-brand-navy/0 transition-colors duration-300 group-hover:bg-brand-navy/5" />
                      </div>

                      {/* Card footer */}
                      <div className="flex items-center justify-between bg-white px-4 py-3">
                        <p className="text-sm font-semibold text-brand-navy">
                          {slide.title}
                        </p>
                        <span
                          className={`${slide.color} rounded-full px-3 py-1 text-[11px] font-semibold text-white`}
                        >
                          {slide.category}
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Arrow buttons */}
            <button
              onClick={scrollPrev}
              className={cn(
                "absolute -left-4 top-1/2 -translate-y-1/2 flex h-10 w-10 items-center justify-center rounded-full border border-gray-200 bg-white shadow-md transition-all hover:border-brand-cyan hover:shadow-brand-cyan/20 md:-left-6",
                !canScrollPrev && "opacity-40"
              )}
              aria-label="Previous slide"
            >
              <ChevronLeft className="h-5 w-5 text-brand-navy" />
            </button>
            <button
              onClick={scrollNext}
              className={cn(
                "absolute -right-4 top-1/2 -translate-y-1/2 flex h-10 w-10 items-center justify-center rounded-full border border-gray-200 bg-white shadow-md transition-all hover:border-brand-cyan hover:shadow-brand-cyan/20 md:-right-6",
                !canScrollNext && "opacity-40"
              )}
              aria-label="Next slide"
            >
              <ChevronRight className="h-5 w-5 text-brand-navy" />
            </button>
          </div>

          {/* Dot indicators */}
          <div className="mt-8 flex items-center justify-center gap-2">
            {SLIDES.map((_, i) => (
              <button
                key={i}
                onClick={() => emblaApi?.scrollTo(i)}
                aria-label={`Go to slide ${i + 1}`}
                className={cn(
                  "h-3 w-3 rounded-full transition-all duration-300",
                  i === selectedIndex
                    ? "bg-brand-navy w-6"
                    : "bg-[#EDF0F2] hover:bg-gray-300"
                )}
              />
            ))}
          </div>
        </ScrollReveal>
      </div>
    </section>
  );
}

