"use client";

import { useState } from "react";
import { Check, Minus } from "lucide-react";
import { cn } from "@/lib/utils";
import { ButtonLink } from "@/components/ui/button-link";
import { ScrollReveal } from "@/components/animations/scroll-reveal";
import {
  PRICING_PLANS,
  COMPARISON_FEATURES,
  getDiscountedPrice,
  type BillingPeriod,
} from "@/lib/constants/pricing";

const BILLING_OPTIONS: { value: BillingPeriod; label: string; badge?: string }[] =
  [
    { value: "monthly", label: "Monthly" },
    { value: "quarterly", label: "Quarterly", badge: "Save 10%" },
    { value: "annually", label: "Annually", badge: "Save 20%" },
  ];

export function PricingSection() {
  const [billing, setBilling] = useState<BillingPeriod>("monthly");

  return (
    <section className="bg-[#f8fafc] py-20 md:py-28" id="pricing">
      <div className="mx-auto max-w-6xl px-4 sm:px-6 lg:px-8">
        <ScrollReveal>
          <h2 className="mb-2 text-center text-[35px] font-bold leading-[45px] text-brand-navy">
            Pricing
          </h2>
          <p className="mx-auto mb-8 max-w-xl text-center text-base leading-relaxed text-gray-500">
            Pick a Flexible Subscription. Get Predictable Output.
          </p>
        </ScrollReveal>

        {/* Billing toggle */}
        <ScrollReveal delay={0.08}>
          <div className="mb-12 flex items-center justify-center">
            <div className="flex items-center gap-1 rounded-full border border-gray-200 bg-white p-1 shadow-sm">
              {BILLING_OPTIONS.map((opt) => (
                <button
                  key={opt.value}
                  onClick={() => setBilling(opt.value)}
                  className={cn(
                    "flex items-center gap-2 rounded-full px-5 py-2 text-sm font-medium transition-all duration-200",
                    billing === opt.value
                      ? "bg-brand-navy text-white shadow-sm"
                      : "text-gray-500 hover:text-brand-navy"
                  )}
                >
                  {opt.label}
                  {opt.badge && (
                    <span
                      className={cn(
                        "rounded-full px-2 py-0.5 text-[10px] font-semibold",
                        billing === opt.value
                          ? "bg-brand-cyan/20 text-brand-cyan"
                          : "bg-green-100 text-green-700"
                      )}
                    >
                      {opt.badge}
                    </span>
                  )}
                </button>
              ))}
            </div>
          </div>
        </ScrollReveal>

        {/* Plan cards */}
        <div className="grid gap-6 md:grid-cols-3">
          {PRICING_PLANS.map((plan, i) => {
            const price = getDiscountedPrice(plan.monthlyPrice, billing);
            return (
              <ScrollReveal key={plan.id} delay={i * 0.1}>
                <div
                  className={cn(
                    "relative flex h-full flex-col rounded-2xl border bg-white p-8 shadow-[0_4px_24px_rgba(171,171,171,0.1)] transition-all duration-300",
                    plan.popular
                      ? "border-[#009ce0] shadow-[0_8px_32px_rgba(0,156,224,0.15)] ring-2 ring-[#009ce0]/20"
                      : "border-gray-100 hover:border-[#009ce0] hover:bg-[#cdebfa]/10 hover:shadow-[0_8px_32px_rgba(0,156,224,0.1)]"
                  )}
                >
                  {plan.popular && (
                    <div className="absolute -top-3.5 left-1/2 -translate-x-1/2">
                      <span className="rounded-full bg-gradient-to-r from-[#21cfff] to-[#019ae6] px-4 py-1 text-xs font-semibold text-white shadow-sm">
                        Most Popular
                      </span>
                    </div>
                  )}

                  <div className="mb-6">
                    <h3 className="mb-1 text-xl font-bold text-brand-navy">
                      {plan.name}
                    </h3>
                    <p className="text-sm text-gray-500">{plan.tagline}</p>
                  </div>

                  <div className="mb-6">
                    <div className="flex items-baseline gap-1">
                      <span className="text-4xl font-black text-brand-navy">
                        ${price.toLocaleString()}
                      </span>
                      <span className="text-sm text-gray-400">/mo</span>
                    </div>
                    {billing !== "monthly" && (
                      <p className="mt-1 text-xs text-gray-400 line-through">
                        ${plan.monthlyPrice.toLocaleString()}/mo
                      </p>
                    )}
                  </div>

                  <ul className="mb-8 flex-1 space-y-3">
                    {plan.features.map((feature) => (
                      <li key={feature} className="flex items-start gap-2.5">
                        <Check className="mt-0.5 h-4 w-4 shrink-0 text-brand-cyan" />
                        <span className="text-sm text-gray-600">{feature}</span>
                      </li>
                    ))}
                  </ul>

                  <ButtonLink
                    href="/book-a-demo"
                    className={cn(
                      "w-full justify-center rounded-full border-0 transition-all",
                      plan.popular
                        ? "bg-gradient-to-r from-[#21cfff] to-[#019ae6] text-white shadow-md hover:brightness-110"
                        : "bg-brand-navy text-white hover:opacity-90"
                    )}
                  >
                    Choose Plan
                  </ButtonLink>
                </div>
              </ScrollReveal>
            );
          })}
        </div>

        {/* Feature comparison table */}
        <ScrollReveal delay={0.15}>
          <div className="mt-16 overflow-hidden rounded-2xl border border-gray-100 bg-white shadow-[0_4px_24px_rgba(171,171,171,0.08)]">
            <div className="grid grid-cols-4 border-b border-gray-100 bg-[#f8fafc] px-6 py-4">
              <div className="text-sm font-semibold text-gray-400">Feature</div>
              {PRICING_PLANS.map((plan) => (
                <div
                  key={plan.id}
                  className="text-center text-sm font-bold text-brand-navy"
                >
                  {plan.name}
                </div>
              ))}
            </div>

            {COMPARISON_FEATURES.map((row, i) => (
              <div
                key={row.label}
                className={cn(
                  "grid grid-cols-4 px-6 py-4",
                  i % 2 === 0 ? "bg-white" : "bg-[#f8fafc]"
                )}
              >
                <div className="text-sm text-gray-600">{row.label}</div>
                {(
                  [row.starter, row.growth, row.pro] as (string | boolean)[]
                ).map((val, j) => (
                  <div key={j} className="flex items-center justify-center">
                    {typeof val === "boolean" ? (
                      val ? (
                        <Check className="h-4 w-4 text-brand-cyan" />
                      ) : (
                        <Minus className="h-4 w-4 text-gray-300" />
                      )
                    ) : (
                      <span className="text-sm font-medium text-brand-navy">
                        {val}
                      </span>
                    )}
                  </div>
                ))}
              </div>
            ))}
          </div>
        </ScrollReveal>

        {/* Custom plan CTA */}
        <ScrollReveal delay={0.2}>
          <div className="mt-10 rounded-2xl border border-dashed border-gray-300 bg-white px-8 py-10 text-center">
            <h3 className="mb-2 text-xl font-bold text-brand-navy">
              Need Something More Flexible?
            </h3>
            <p className="mx-auto mb-6 max-w-md text-sm text-gray-500">
              High volume, specific platforms, or custom workflows — we&apos;ll design
              a plan built exactly for your agency&apos;s needs.
            </p>
            <ButtonLink
              href="/book-a-demo"
              className="rounded-full border-0 bg-gradient-to-r from-[#21cfff] to-[#019ae6] px-8 text-white shadow-md hover:brightness-110"
            >
              Build Your Custom Plan
            </ButtonLink>
          </div>
        </ScrollReveal>
      </div>
    </section>
  );
}

